-- Starter data for Pastel Treats (generated from src/data/seed.js). Safe to run once.
-- Prices are SAMPLE values: edit them in the app under Admin → Menu & Pricing.

insert into public.settings(id, data) values (1, '{"business_name":"Pastel Treats","tagline":"Cakes and everything nice","brand_line":"Premium home baker","hero_headline":"Handcrafted with Love, Baked for Your Special Moments.","hero_intro":"Pastel Treats is a premium home baking house in Dindigul — carefully sourced and selected premium ingredients go into our cakes, entremets, brownies and cookies, baked fresh to order in small batches by a certified pastry chef and finished by hand for the people you love.\n\nWe use only Van Houten couverture and premium Callebaut chocolates, and only fresh buttercream frosting.","baker_name":"Vaishnavi","baker_title":"Certified pastry chef","baker_intro":"Hi, I am Vaishnavi, a certified, passionate baker from Lavonne Academy of Baking Science & Pastry Arts. Every Pastel Treats order is baked by me in small batches, fresh for your celebration.","baker_image":"images/baker.webp","promo_banner":"","announcements":[],"orders_paused":false,"orders_paused_message":"","whatsapp":"919566883196","phone":"+91 95668 83196","phone2":"","email":"","instagram":"https://instagram.com/pasteltreats_28","pickup_address":"Pastel Treats, Dindigul","maps_link":"https://maps.app.goo.gl/AroAhgnvaNr5MoWy8?g_st=ac","pickup_instructions":"Please come at your chosen time slot and message us on WhatsApp when you arrive. Carry cakes flat and keep them cool.","business_hours":"Mon – Sat: 9:00 AM – 7:00 PM · Sun: 11:00 AM – 7:00 PM (app & WhatsApp only)","order_channel_note":"Please place orders in the app — it books your slot, gives you an order ID and lets you track it. WhatsApp us if you have any doubts.","timezone":"Asia/Kolkata","lead_time_hours":48,"cancel_full_refund_hours":48,"closed_weekdays":[],"no_call_weekdays":[0],"max_orders_per_day":10,"max_deliveries_per_day":null,"home_delivery_enabled":false,"courier_enabled":true,"courier_note":"Brownies, blondies, cookie boxes and ragi puffs can be sent by courier. Courier charges are extra — we confirm them before you pay.","advance_mode":"percent","advance_value":50,"upi_id":"","upi_name":"Pastel Treats","upi_qr_url":"","cash_pickup":true,"cash_delivery":false,"cash_for":"balance","gateway_enabled":false,"razorpay_key_id":"","allow_out_of_zone_requests":false,"reminder_days":[30,14,7],"segments":{"frequent_orders":4,"high_spend":5000,"inactive_days":120},"policies":{"ordering":"Please order 48 hrs (2 days) prior to your pickup time. Submitting an order is a request — it is confirmed only after we review it and receive the advance.","advance":"A 50% advance confirms your order. The balance is paid at pickup.","pickup":"All orders are self pickup from our location (see the map link) at the time slot you choose. Please arrive within your slot and message us on WhatsApp when you reach.","delivery":"We do not do home delivery. Brownies, blondies, cookie boxes and ragi puffs can be couriered — courier charges are extra and confirmed before you pay.","cancellation":"Cancel more than 48 hrs (2 days) before your slot for a full refund of the advance. Within 48 hrs, the advance is non-refundable because ingredients have been bought and prep has begun.","refund":"Approved refunds are returned to the original UPI account within 5–7 working days.","custom":"Customisation is extra and quoted individually. Your reference picture is inspiration — hand-finished bakes will vary slightly. We confirm the final price before you pay.","missed_pickup":"If an order is not collected in the chosen slot, we hold it refrigerated until the end of the day. After that it cannot be refunded.","changes":"Changes to flavour or design are possible up to 48 hrs (2 days) before the slot, subject to availability.","allergens":"Our kitchen handles eggs, dairy, gluten, nuts and soy. Please tell us about any allergy before ordering.","storage":"Refrigerate cream cakes, mousse and tres leches. Bring cakes to room temperature for 20–30 minutes before serving. Best eaten within 2 days.","privacy":"We store your name, mobile number and (only if you choose) special dates to process orders and send reminders you agreed to. We never sell your data. Ask us anytime to correct or delete it.","terms":"Prices marked “onwards” depend on flavour, size and design. The price confirmed on your order is the price you pay."}}'::jsonb)
on conflict (id) do nothing;

