insert into public.time_slots(label, start_time, end_time, capacity, weekdays, sort) select '9:00 – 11:00 AM', '09:00', '11:00', 3, '{1,2,3,4,5,6}'::int[], 1 where not exists (select 1 from public.time_slots where label = '9:00 – 11:00 AM');
