insert into public.time_slots(label, start_time, end_time, capacity, weekdays, sort) select '1:00 – 3:00 PM', '13:00', '15:00', 3, null, 3 where not exists (select 1 from public.time_slots where label = '1:00 – 3:00 PM');
insert into public.time_slots(label, start_time, end_time, capacity, weekdays, sort) select '3:00 – 5:00 PM', '15:00', '17:00', 3, null, 4 where not exists (select 1 from public.time_slots where label = '3:00 – 5:00 PM');
insert into public.time_slots(label, start_time, end_time, capacity, weekdays, sort) select '5:00 – 7:00 PM', '17:00', '19:00', 4, null, 5 where not exists (select 1 from public.time_slots where label = '5:00 – 7:00 PM');

